-- The table and index declarations of a program built on this library, each as that program
-- writes it. One statement to a line, ended by `;`. A table comes after the tables it
-- references. `tests/declarations.rs` declares every one and reads it back.

CREATE TABLE cg_schema_version (id INTEGER PRIMARY KEY, version INTEGER NOT NULL, installed_at TXID NOT NULL) SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE contexts (id UUID PRIMARY KEY CONTEXT_ID, name TEXT NOT NULL UNIQUE, labels JSON, properties JSON, created_at TXID NOT NULL) SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE events (id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), connector_id TEXT NOT NULL, adapter_version TEXT NOT NULL, anchor_declaration_version TEXT NOT NULL, source_instance_ref TEXT NOT NULL, session_ref TEXT NOT NULL, source_event_key TEXT NOT NULL, source_position JSON NOT NULL, seq INTEGER NOT NULL, content_hash TEXT NOT NULL, anchor_count INTEGER NOT NULL, anchor_set_hash TEXT NOT NULL, occurred_at TIMESTAMP, author TEXT NOT NULL, kind TEXT NOT NULL, render_role TEXT NOT NULL, interaction_ref TEXT, text TEXT, payload JSON NOT NULL DEFAULT '{}', anchors JSON NOT NULL DEFAULT '{}', source_remainder JSON NOT NULL DEFAULT '{}', coverage TEXT NOT NULL, UNIQUE (context_id, id), UNIQUE (context_id, connector_id, session_ref, source_event_key), UNIQUE (context_id, connector_id, source_instance_ref, seq)) IMMUTABLE SYNC OFF SYNC CONFLICT KEEP FIRST MAINTAIN COUNT (context_id), (context_id, connector_id, source_instance_ref);
CREATE TABLE event_anchors (id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), event_id UUID NOT NULL REFERENCES events(id), correlation_scope_hash TEXT NOT NULL, declaration_version TEXT NOT NULL, connector_id TEXT NOT NULL, source_instance_ref TEXT NOT NULL, session_ref TEXT NOT NULL, render_role TEXT NOT NULL, interaction_ref TEXT, key TEXT NOT NULL, value TEXT NOT NULL, identity_value TEXT NOT NULL, original_value JSON NOT NULL, UNIQUE (context_id, id), UNIQUE (context_id, event_id, declaration_version, key, identity_value), FOREIGN KEY (context_id, event_id) REFERENCES events(context_id, id)) IMMUTABLE SYNC OFF SYNC CONFLICT KEEP FIRST MAINTAIN COUNT NONE;
CREATE TABLE event_local_commits (event_id UUID PRIMARY KEY REFERENCES events(id), context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), committed_at TXID NOT NULL, FOREIGN KEY (context_id, event_id) REFERENCES events(context_id, id)) IMMUTABLE SYNC OFF MAINTAIN COUNT NONE;
CREATE TABLE adapter_coverage_gaps (id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), connector_id TEXT NOT NULL, captured_adapter_version TEXT NOT NULL, fingerprint_sha256 TEXT NOT NULL, first_seen_at TXID NOT NULL, last_seen_at TXID NOT NULL, UNIQUE (context_id, id), UNIQUE (context_id, connector_id, captured_adapter_version, fingerprint_sha256)) SYNC OFF MAINTAIN COUNT (context_id);
CREATE TABLE adapter_coverage_gap_events (context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), gap_id UUID NOT NULL REFERENCES adapter_coverage_gaps(id), event_id UUID NOT NULL REFERENCES events(id), PRIMARY KEY (context_id, gap_id, event_id), FOREIGN KEY (context_id, gap_id) REFERENCES adapter_coverage_gaps(context_id, id), FOREIGN KEY (context_id, event_id) REFERENCES events(context_id, id)) IMMUTABLE SYNC OFF;
CREATE TABLE event_interpretation_generations (id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), connector_id TEXT NOT NULL, accepted_source_declarations JSON NOT NULL, target_interpretation_version TEXT NOT NULL, target_adapter_version TEXT NOT NULL, target_anchor_declaration_version TEXT NOT NULL, mapping_contract_id TEXT NOT NULL, mapping_contract_sha256 TEXT NOT NULL, event_count INTEGER NOT NULL, ordered_source_set_sha256 TEXT NOT NULL, source_content_sha256 TEXT NOT NULL, capture_ordinal INTEGER NOT NULL DEFAULT 0, build_ordinal INTEGER NOT NULL DEFAULT 0, claim_end_ordinal INTEGER, claim_membership_sha256 TEXT, lease_epoch INTEGER NOT NULL DEFAULT 0, lease_token TEXT, lease_expires_at TIMESTAMP, state TEXT NOT NULL, eligible_event_count INTEGER NOT NULL DEFAULT 0, interpreted_event_count INTEGER NOT NULL DEFAULT 0, failed_event_count INTEGER NOT NULL DEFAULT 0, effective_content_sha256 TEXT, sanitized_failure TEXT, started_at TXID NOT NULL, completed_at TXID, activated_at TXID, activation_receipt JSON, UNIQUE (context_id, id), UNIQUE (context_id, connector_id, id), UNIQUE (context_id, connector_id, target_interpretation_version, event_count, ordered_source_set_sha256)) SYNC OFF;
CREATE TABLE event_interpretation_source_events (context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), generation_id UUID NOT NULL REFERENCES event_interpretation_generations(id), ordinal INTEGER NOT NULL, event_id UUID NOT NULL REFERENCES events(id), source_instance_ref TEXT NOT NULL, source_sequence INTEGER NOT NULL, source_row_sha256 TEXT NOT NULL, PRIMARY KEY (context_id, generation_id, ordinal), UNIQUE (context_id, generation_id, event_id), FOREIGN KEY (context_id, generation_id) REFERENCES event_interpretation_generations(context_id, id), FOREIGN KEY (context_id, event_id) REFERENCES events(context_id, id)) IMMUTABLE SYNC OFF;
CREATE TABLE event_interpretation_values (context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), generation_id UUID NOT NULL REFERENCES event_interpretation_generations(id), event_id UUID NOT NULL REFERENCES events(id), captured_content_sha256 TEXT NOT NULL, occurred_at TIMESTAMP, author TEXT NOT NULL, kind TEXT NOT NULL, render_role TEXT NOT NULL, interaction_ref TEXT, text TEXT, payload JSON NOT NULL, anchors JSON NOT NULL, coverage TEXT NOT NULL, effective_sha256 TEXT NOT NULL, created_at TXID NOT NULL, PRIMARY KEY (context_id, generation_id, event_id), UNIQUE (context_id, generation_id, event_id), FOREIGN KEY (context_id, generation_id) REFERENCES event_interpretation_generations(context_id, id), FOREIGN KEY (context_id, event_id) REFERENCES events(context_id, id)) IMMUTABLE SYNC OFF;
CREATE TABLE event_interpretation_anchors (id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), generation_id UUID NOT NULL REFERENCES event_interpretation_generations(id), event_id UUID NOT NULL REFERENCES events(id), declaration_version TEXT NOT NULL, key TEXT NOT NULL, canonical_value TEXT NOT NULL, identity_value TEXT NOT NULL, original_value JSON NOT NULL, UNIQUE (context_id, id), UNIQUE (context_id, generation_id, event_id, declaration_version, key, identity_value), FOREIGN KEY (context_id, generation_id, event_id) REFERENCES event_interpretation_values(context_id, generation_id, event_id)) IMMUTABLE SYNC OFF;
CREATE TABLE event_interpretation_heads (context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), connector_id TEXT NOT NULL, generation_id UUID NOT NULL REFERENCES event_interpretation_generations(id), activated_at TXID NOT NULL, PRIMARY KEY (context_id, connector_id), FOREIGN KEY (context_id, connector_id, generation_id) REFERENCES event_interpretation_generations(context_id, connector_id, id)) SYNC OFF;
CREATE TABLE event_context_revisions (context_id UUID CONTEXT_ID PRIMARY KEY REFERENCES contexts(id), revision_tx TXID NOT NULL) SYNC OFF;
CREATE TABLE event_context_counts (context_id UUID CONTEXT_ID PRIMARY KEY REFERENCES contexts(id), captured_events INTEGER NOT NULL, complete_events INTEGER NOT NULL, opaque_events INTEGER NOT NULL, payload_refused_events INTEGER NOT NULL, source_declared_missing_events INTEGER NOT NULL) SYNC OFF;
CREATE TABLE event_context_sessions (context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), connector_id TEXT NOT NULL, session_ref TEXT NOT NULL, event_count INTEGER NOT NULL, latest_occurred_at TIMESTAMP, PRIMARY KEY (context_id, connector_id, session_ref)) SYNC OFF;
CREATE TABLE event_search_request_headers (request_id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), running_generation_id UUID, running_owner_token TEXT, UNIQUE (context_id, request_id)) SYNC OFF;
CREATE TABLE event_search_request_selections (context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), request_id UUID NOT NULL, ordinal INTEGER NOT NULL, connector_id TEXT NOT NULL, session_ref TEXT NOT NULL, source_instance_ref TEXT NOT NULL, frontier INTEGER NOT NULL, PRIMARY KEY (context_id, request_id, ordinal), FOREIGN KEY (context_id, request_id) REFERENCES event_search_request_headers(context_id, request_id)) SYNC OFF;
CREATE TABLE event_search_refusal_headers (request_id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), UNIQUE (context_id, request_id)) SYNC OFF;
CREATE TABLE event_search_refusal_frontiers (context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), request_id UUID NOT NULL, ordinal INTEGER NOT NULL, connector_id TEXT NOT NULL, session_ref TEXT NOT NULL, source_instance_ref TEXT NOT NULL, frontier INTEGER NOT NULL, PRIMARY KEY (context_id, request_id, ordinal), FOREIGN KEY (context_id, request_id) REFERENCES event_search_refusal_headers(context_id, request_id)) SYNC OFF;
CREATE TABLE event_search_work_policies (context_id UUID CONTEXT_ID PRIMARY KEY REFERENCES contexts(id), search_order TEXT NOT NULL, search_sessions INTEGER) SYNC OFF;
CREATE TABLE event_placement (id INTEGER PRIMARY KEY, expected_policy TEXT NOT NULL, first_event_tx TXID, installation_table_baseline JSON) SYNC OFF;
CREATE TABLE context_bindings (namespace TEXT NOT NULL, opaque_reference TEXT NOT NULL, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), PRIMARY KEY (namespace, opaque_reference)) SYNC OFF;
CREATE TABLE event_source_locators (context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), connector_id TEXT NOT NULL, source_locator_ref TEXT NOT NULL, source_instance_ref TEXT NOT NULL, session_ref TEXT NOT NULL, provisional_empty BOOLEAN NOT NULL, adapter_version TEXT NOT NULL, anchor_declaration_version TEXT NOT NULL, PRIMARY KEY (context_id, connector_id, source_locator_ref)) SYNC OFF;
CREATE TABLE event_source_checkpoints (context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), connector_id TEXT NOT NULL, source_instance_ref TEXT NOT NULL, session_ref TEXT NOT NULL, adapter_version TEXT NOT NULL, anchor_declaration_version TEXT NOT NULL, checkpoint JSON NOT NULL, source_position JSON NOT NULL, committed_byte_offset INTEGER NOT NULL, prefix_sha256 TEXT NOT NULL, observed_source_len INTEGER NOT NULL, latest_event_seq INTEGER, last_successful_tx TXID NOT NULL, PRIMARY KEY (context_id, connector_id, source_instance_ref)) SYNC OFF;
CREATE TABLE event_source_ordering (declaration_hash TEXT NOT NULL UNIQUE, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), connector_id TEXT NOT NULL, source_instance_ref TEXT NOT NULL, adapter_version TEXT NOT NULL, source_position_order JSON NOT NULL, PRIMARY KEY (context_id, connector_id, source_instance_ref)) SYNC OFF;
CREATE TABLE intentions (id UUID PRIMARY KEY, description TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), origin TEXT NOT NULL, origin_ref UUID, blueprint_id UUID, bindings JSON, blueprint_proposal TEXT, blueprint_catalog_id TEXT, properties JSON, tags JSON, created_at TXID NOT NULL, UNIQUE (context_id, id)) STATE MACHINE (status: active -> [paused, superseded, archived], paused -> [active, superseded, archived]) SYNC TWO WAY SYNC CONFLICT KEEP LATEST MAINTAIN COUNT (context_id);
CREATE TABLE decisions (id UUID PRIMARY KEY, decision_type TEXT NOT NULL IMMUTABLE, description TEXT NOT NULL IMMUTABLE, reasoning JSON, confidence REAL, status TEXT NOT NULL DEFAULT 'active', agent_id TEXT, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), properties JSON, tags JSON, created_at TXID NOT NULL, UNIQUE (context_id, id)) STATE MACHINE (status: active -> [superseded, archived, invalidated]) SYNC TWO WAY SYNC CONFLICT KEEP LATEST MAINTAIN COUNT (context_id);
CREATE TABLE outcomes (id UUID NOT NULL UNIQUE, decision_id UUID NOT NULL REFERENCES decisions(id), context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), success BOOLEAN NOT NULL, notes TEXT, recorded_at TXID NOT NULL, PRIMARY KEY (context_id, decision_id), UNIQUE (context_id, id), FOREIGN KEY (context_id, decision_id) REFERENCES decisions(context_id, id)) SYNC TWO WAY SYNC CONFLICT KEEP LATEST;
CREATE TABLE conflicts (id UUID NOT NULL UNIQUE, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), older_decision_id UUID NOT NULL REFERENCES decisions(id), newer_decision_id UUID NOT NULL REFERENCES decisions(id), threatened_intention_ids JSON NOT NULL DEFAULT '[]', intention_in_tension BOOLEAN NOT NULL, detected_at TXID NOT NULL, PRIMARY KEY (context_id, older_decision_id, newer_decision_id), FOREIGN KEY (context_id, older_decision_id) REFERENCES decisions(context_id, id), FOREIGN KEY (context_id, newer_decision_id) REFERENCES decisions(context_id, id)) IMMUTABLE SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE entities (id UUID PRIMARY KEY, entity_type TEXT NOT NULL, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), properties JSON, tags JSON, created_at TXID NOT NULL, UNIQUE (context_id, id)) STATE MACHINE (status: active -> [archived]) SYNC TWO WAY SYNC CONFLICT KEEP LATEST;
CREATE TABLE observations (id UUID PRIMARY KEY, observation_type TEXT NOT NULL, observed_properties JSON NOT NULL, state_delta JSON NOT NULL, properties JSON, source TEXT NOT NULL, entity_id UUID NOT NULL REFERENCES entities(id), context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), timestamp TIMESTAMP NOT NULL, created_at TXID NOT NULL, UNIQUE (context_id, id), UNIQUE (context_id, entity_id, id), FOREIGN KEY (context_id, entity_id) REFERENCES entities(context_id, id)) IMMUTABLE SYNC TWO WAY SYNC CONFLICT KEEP FIRST MAINTAIN COUNT (context_id);
CREATE TABLE invalidations (id UUID NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'pending', context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), affected_decision_id UUID NOT NULL REFERENCES decisions(id), trigger_observation_id UUID NOT NULL REFERENCES observations(id), reason TEXT, basis_diff JSON NOT NULL, cascade_from UUID REFERENCES decisions(id), severity TEXT NOT NULL, threatened_intention_ids JSON NOT NULL DEFAULT '[]', intention_now_un_served BOOLEAN NOT NULL DEFAULT false, detected_at TXID NOT NULL, resolved_at TXID, resolution_action TEXT, resolution_decision_id UUID, PRIMARY KEY (context_id, affected_decision_id), FOREIGN KEY (context_id, affected_decision_id) REFERENCES decisions(context_id, id), FOREIGN KEY (context_id, trigger_observation_id) REFERENCES observations(context_id, id), FOREIGN KEY (context_id, cascade_from) REFERENCES decisions(context_id, id), FOREIGN KEY (context_id, resolution_decision_id) REFERENCES decisions(context_id, id)) STATE MACHINE (status: pending -> [acknowledged], acknowledged -> [resolved, dismissed]) SYNC TWO WAY SYNC CONFLICT KEEP LATEST;
CREATE TABLE evidence (id UUID PRIMARY KEY, observation_id UUID NOT NULL REFERENCES observations(id), context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), kind TEXT NOT NULL, source_ref TEXT NOT NULL, mime_type TEXT, content_hash TEXT, captured_at TIMESTAMP, captured_at_nanos INTEGER, byte_range JSON, time_range_ms JSON, frame_index INTEGER, region JSON, producer JSON, text_projection TEXT, derived_from UUID REFERENCES evidence(id), retention_status TEXT NOT NULL, media_retention_until TIMESTAMP, media_retention_until_nanos INTEGER, properties JSON, supply_order INTEGER NOT NULL, vector_text VECTOR(768), vector_vision VECTOR(512), UNIQUE (context_id, id), FOREIGN KEY (context_id, observation_id) REFERENCES observations(context_id, id), FOREIGN KEY (context_id, derived_from) REFERENCES evidence(context_id, id)) IMMUTABLE SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE embedding_spaces (embedding_space_id TEXT PRIMARY KEY, dimension INTEGER NOT NULL, metric TEXT NOT NULL, model_family TEXT, model_name TEXT, model_version TEXT, supported_evidence_kinds JSON, default_for_evidence_kind TEXT, bindings JSON, created_at TXID NOT NULL) SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE event_search_generations (id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), interpretation_generation_id UUID, interpretation_snapshot JSON NOT NULL, interpretation_snapshot_sha256 TEXT NOT NULL, event_count INTEGER NOT NULL, ordered_source_set_sha256 TEXT NOT NULL, source_content_sha256 TEXT NOT NULL DEFAULT '', capture_ordinal INTEGER NOT NULL DEFAULT 0, renderer_id TEXT NOT NULL, renderer_version TEXT NOT NULL, renderer_profile JSON NOT NULL, embedding_space_id TEXT NOT NULL REFERENCES embedding_spaces(embedding_space_id), encoding_profile TEXT NOT NULL, state TEXT NOT NULL, required_event_count INTEGER NOT NULL DEFAULT 0, searchable_event_count INTEGER NOT NULL DEFAULT 0, searchable_excluded_event_count INTEGER NOT NULL DEFAULT 0, eligible_event_count INTEGER NOT NULL DEFAULT 0, rendered_event_count INTEGER NOT NULL DEFAULT 0, embedded_event_count INTEGER NOT NULL DEFAULT 0, excluded_event_count INTEGER NOT NULL DEFAULT 0, failed_event_count INTEGER NOT NULL DEFAULT 0, passage_count INTEGER NOT NULL DEFAULT 0, started_at TXID NOT NULL, completed_at TXID, finalized_event_revision_tx TXID, last_attempt_at TXID, last_attempt_token UUID NOT NULL, sanitized_failure TEXT, UNIQUE (context_id, id), FOREIGN KEY (context_id, interpretation_generation_id) REFERENCES event_interpretation_generations(context_id, id)) SYNC OFF;
CREATE TABLE event_search_source_events (membership_id UUID NOT NULL UNIQUE, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), generation_id UUID NOT NULL REFERENCES event_search_generations(id), ordinal INTEGER NOT NULL, event_id UUID NOT NULL REFERENCES events(id), connector_id TEXT NOT NULL, source_instance_ref TEXT NOT NULL, session_ref TEXT NOT NULL, source_sequence INTEGER NOT NULL, effective_interpretation_generation_id UUID, captured_source_sha256 TEXT NOT NULL, effective_source_sha256 TEXT NOT NULL, PRIMARY KEY (context_id, generation_id, ordinal), UNIQUE (context_id, generation_id, event_id), FOREIGN KEY (context_id, generation_id) REFERENCES event_search_generations(context_id, id), FOREIGN KEY (context_id, event_id) REFERENCES events(context_id, id), FOREIGN KEY (context_id, effective_interpretation_generation_id, event_id) REFERENCES event_interpretation_values(context_id, generation_id, event_id)) IMMUTABLE SYNC OFF;
CREATE TABLE event_search_session_progress (context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), generation_id UUID NOT NULL REFERENCES event_search_generations(id), connector_id TEXT NOT NULL, session_ref TEXT NOT NULL, event_count INTEGER NOT NULL, committed_event_count INTEGER NOT NULL DEFAULT 0, eligible_event_count INTEGER NOT NULL DEFAULT 0, excluded_event_count INTEGER NOT NULL DEFAULT 0, searchable_event_count INTEGER NOT NULL DEFAULT 0, no_searchable_text_event_count INTEGER NOT NULL DEFAULT 0, is_required BOOLEAN NOT NULL DEFAULT false, is_published BOOLEAN NOT NULL DEFAULT false, PRIMARY KEY (context_id, generation_id, connector_id, session_ref), FOREIGN KEY (context_id, generation_id) REFERENCES event_search_generations(context_id, id)) SYNC OFF;
CREATE TABLE event_search_passages (id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), generation_id UUID NOT NULL REFERENCES event_search_generations(id), connector_id TEXT NOT NULL, session_ref TEXT NOT NULL, source_instance_ref TEXT NOT NULL, passage_ordinal INTEGER NOT NULL, first_event_sequence INTEGER NOT NULL, last_event_sequence INTEGER NOT NULL, rendered_text TEXT NOT NULL, content_sha256 TEXT NOT NULL, vector_text VECTOR(768) PARTITION_KEY (context_id, generation_id) MAX_PARTITIONS 4096 SEARCH_MODE AUTO, dimension INTEGER NOT NULL, is_current BOOLEAN NOT NULL, is_searchable BOOLEAN NOT NULL DEFAULT true, created_at TXID NOT NULL, UNIQUE (context_id, id), UNIQUE (context_id, generation_id, id), UNIQUE (context_id, generation_id, connector_id, source_instance_ref, passage_ordinal), FOREIGN KEY (context_id, generation_id) REFERENCES event_search_generations(context_id, id)) HISTORY CURRENT ONLY SYNC OFF;
CREATE TABLE event_search_passage_sources (context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), generation_id UUID NOT NULL REFERENCES event_search_generations(id), passage_id UUID NOT NULL REFERENCES event_search_passages(id), event_id UUID NOT NULL REFERENCES events(id), connector_id TEXT NOT NULL, session_ref TEXT NOT NULL, source_instance_ref TEXT NOT NULL, source_order INTEGER NOT NULL, event_start_byte INTEGER, event_end_byte INTEGER, passage_start_byte INTEGER NOT NULL, passage_end_byte INTEGER NOT NULL, PRIMARY KEY (context_id, passage_id, source_order), FOREIGN KEY (context_id, generation_id, passage_id) REFERENCES event_search_passages(context_id, generation_id, id), FOREIGN KEY (context_id, event_id) REFERENCES events(context_id, id)) IMMUTABLE SYNC OFF;
CREATE TABLE event_search_embedding_handles (id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), generation_id UUID NOT NULL REFERENCES event_search_generations(id), passage_id UUID NOT NULL REFERENCES event_search_passages(id), embedding_space_id TEXT NOT NULL REFERENCES embedding_spaces(embedding_space_id), produced_by JSON NOT NULL, producer_system TEXT NOT NULL, created_at TXID NOT NULL, UNIQUE (context_id, id), UNIQUE (context_id, passage_id, embedding_space_id), FOREIGN KEY (context_id, generation_id, passage_id) REFERENCES event_search_passages(context_id, generation_id, id)) IMMUTABLE SYNC OFF;
CREATE TABLE event_search_heads (context_id UUID CONTEXT_ID PRIMARY KEY REFERENCES contexts(id), generation_id UUID NOT NULL REFERENCES event_search_generations(id), activated_at TXID NOT NULL, FOREIGN KEY (context_id, generation_id) REFERENCES event_search_generations(context_id, id)) SYNC OFF;
CREATE TABLE event_search_cursors (context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), generation_id UUID NOT NULL REFERENCES event_search_generations(id), connector_id TEXT NOT NULL, source_instance_ref TEXT NOT NULL, session_ref TEXT NOT NULL, committed_sequence INTEGER NOT NULL, open_tail_start_sequence INTEGER, open_tail_members JSON NOT NULL, open_tail_passage_id UUID, watermark_sha256 TEXT NOT NULL, updated_at TXID NOT NULL, PRIMARY KEY (context_id, generation_id, connector_id, source_instance_ref, session_ref), FOREIGN KEY (context_id, generation_id) REFERENCES event_search_generations(context_id, id)) SYNC OFF;
CREATE TABLE event_search_leases (context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), generation_id UUID NOT NULL REFERENCES event_search_generations(id), owner_token TEXT NOT NULL, lease_epoch INTEGER NOT NULL, claimed_connector_id TEXT, claimed_source_instance_ref TEXT, claimed_start_sequence INTEGER, claimed_end_sequence INTEGER, cursor_sha256 TEXT NOT NULL, expires_at TIMESTAMP NOT NULL, PRIMARY KEY (context_id, generation_id), FOREIGN KEY (context_id, generation_id) REFERENCES event_search_generations(context_id, id)) SYNC OFF;
CREATE TABLE embedding_space_bindings (embedding_space_id TEXT NOT NULL REFERENCES embedding_spaces(embedding_space_id), table_name TEXT NOT NULL, vector_column TEXT NOT NULL, PRIMARY KEY (embedding_space_id, table_name, vector_column)) SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE evidence_embedding_handles (id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), target_id UUID NOT NULL REFERENCES evidence(id), embedding_space_id TEXT NOT NULL REFERENCES embedding_spaces(embedding_space_id), produced_by JSON, producer_system TEXT NOT NULL, created_at TXID NOT NULL, FOREIGN KEY (context_id, target_id) REFERENCES evidence(context_id, id)) IMMUTABLE SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE entity_reference_embedding_handles (id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), target_id UUID NOT NULL, embedding_space_id TEXT NOT NULL REFERENCES embedding_spaces(embedding_space_id), produced_by JSON, producer_system TEXT NOT NULL, created_at TXID NOT NULL, FOREIGN KEY (context_id, target_id) REFERENCES entities(context_id, id)) IMMUTABLE SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE entity_reference_embeddings_128 (id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), entity_id UUID NOT NULL, label TEXT, vector VECTOR(128), embedding_space_id TEXT NOT NULL REFERENCES embedding_spaces(embedding_space_id), produced_by JSON, created_at TXID NOT NULL, UNIQUE (entity_id, label), UNIQUE (context_id, id), FOREIGN KEY (context_id, entity_id) REFERENCES entities(context_id, id)) SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE entity_reference_embeddings_256 (id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), entity_id UUID NOT NULL, label TEXT, vector VECTOR(256), embedding_space_id TEXT NOT NULL REFERENCES embedding_spaces(embedding_space_id), produced_by JSON, created_at TXID NOT NULL, UNIQUE (entity_id, label), UNIQUE (context_id, id), FOREIGN KEY (context_id, entity_id) REFERENCES entities(context_id, id)) SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE entity_reference_embeddings_512 (id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), entity_id UUID NOT NULL, label TEXT, vector VECTOR(512), embedding_space_id TEXT NOT NULL REFERENCES embedding_spaces(embedding_space_id), produced_by JSON, created_at TXID NOT NULL, UNIQUE (entity_id, label), UNIQUE (context_id, id), FOREIGN KEY (context_id, entity_id) REFERENCES entities(context_id, id)) SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE entity_reference_embeddings_768 (id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), entity_id UUID NOT NULL, label TEXT, vector VECTOR(768), embedding_space_id TEXT NOT NULL REFERENCES embedding_spaces(embedding_space_id), produced_by JSON, created_at TXID NOT NULL, UNIQUE (entity_id, label), UNIQUE (context_id, id), FOREIGN KEY (context_id, entity_id) REFERENCES entities(context_id, id)) SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE reindex_cursors (embedding_space_id TEXT PRIMARY KEY REFERENCES embedding_spaces(embedding_space_id), status TEXT NOT NULL, owner_run_id TEXT NOT NULL, lease_epoch INTEGER NOT NULL, last_committed_cursor INTEGER NOT NULL, from_producer JSON, to_producer JSON, started_at TXID NOT NULL, last_advanced_at TXID NOT NULL) SYNC TWO WAY SYNC CONFLICT KEEP LATEST;
CREATE TABLE evidence_availability_log (id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), evidence_id UUID NOT NULL REFERENCES evidence(id), status TEXT NOT NULL, recorded_at_txid TXID NOT NULL, recorded_at TIMESTAMP, FOREIGN KEY (context_id, evidence_id) REFERENCES evidence(context_id, id)) IMMUTABLE SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE signatures (id UUID PRIMARY KEY, signature_type TEXT NOT NULL, description TEXT NOT NULL, match_criteria JSON NOT NULL, scope_labels JSON NOT NULL, confidence REAL NOT NULL, origin_context_ids JSON, status TEXT NOT NULL DEFAULT 'active', created_at TXID NOT NULL, last_matched_at TXID) SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE signature_aggregates (signature_id TEXT PRIMARY KEY, signature_row_id UUID REFERENCES signatures(id), embedding_space_id TEXT NOT NULL, producer JSON NOT NULL, centroid JSON NOT NULL, member_count INTEGER NOT NULL, scope_labels JSON NOT NULL, created_at TXID NOT NULL) SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE signature_producer_lineage (id UUID PRIMARY KEY, signature_id TEXT NOT NULL, signature_row_id UUID REFERENCES signatures(id), contribution_role TEXT NOT NULL, observation_id UUID NOT NULL, evidence_id UUID NOT NULL, embedding_id UUID NOT NULL, embedding_space_id TEXT NOT NULL, producer JSON NOT NULL, created_at TXID NOT NULL) SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE digests (id UUID PRIMARY KEY, source TEXT NOT NULL, session_ref TEXT, summary TEXT NOT NULL, kind TEXT NOT NULL, vector_text VECTOR(768), dimension INTEGER NOT NULL, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), properties JSON, created_at TXID NOT NULL, UNIQUE (context_id, id)) IMMUTABLE SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE digest_embedding_handles (id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), target_id UUID NOT NULL REFERENCES digests(id), embedding_space_id TEXT NOT NULL REFERENCES embedding_spaces(embedding_space_id), produced_by JSON, producer_system TEXT NOT NULL, created_at TXID NOT NULL, FOREIGN KEY (context_id, target_id) REFERENCES digests(context_id, id)) IMMUTABLE SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE blueprints (id UUID PRIMARY KEY, canonical_description TEXT NOT NULL, category TEXT NOT NULL, slots JSON NOT NULL, default_config_shape JSON, version TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', created_at TIMESTAMP NOT NULL) SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE edges (id UUID PRIMARY KEY, source_id UUID NOT NULL, target_id UUID NOT NULL, edge_type TEXT NOT NULL, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), valid_from TXID NOT NULL, valid_to TXID, properties JSON, UNIQUE (source_id, target_id, edge_type)) DAG('CITES') SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE entity_snapshots (id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), entity_id UUID NOT NULL REFERENCES entities(id), data JSON NOT NULL, valid_from TXID NOT NULL, valid_to TXID, UNIQUE (context_id, id), UNIQUE (context_id, entity_id, id), FOREIGN KEY (context_id, entity_id) REFERENCES entities(context_id, id)) IMMUTABLE SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE entity_snapshot_observations (id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), entity_id UUID NOT NULL REFERENCES entities(id), snapshot_id UUID NOT NULL REFERENCES entity_snapshots(id), observation_id UUID NOT NULL REFERENCES observations(id), observation_order INTEGER NOT NULL, created_at TXID NOT NULL, UNIQUE (context_id, entity_id, snapshot_id, observation_order), UNIQUE (context_id, entity_id, snapshot_id, observation_id), FOREIGN KEY (context_id, entity_id) REFERENCES entities(context_id, id), FOREIGN KEY (context_id, entity_id, snapshot_id) REFERENCES entity_snapshots(context_id, entity_id, id), FOREIGN KEY (context_id, entity_id, observation_id) REFERENCES observations(context_id, entity_id, id)) SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE decision_basis_snapshots (id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), decision_id UUID NOT NULL REFERENCES decisions(id), entity_id UUID NOT NULL REFERENCES entities(id), snapshot_id UUID NOT NULL REFERENCES entity_snapshots(id), basis_order INTEGER NOT NULL, created_at TXID NOT NULL, UNIQUE (context_id, decision_id, basis_order), UNIQUE (context_id, decision_id, snapshot_id), FOREIGN KEY (context_id, decision_id) REFERENCES decisions(context_id, id), FOREIGN KEY (context_id, entity_id) REFERENCES entities(context_id, id), FOREIGN KEY (context_id, entity_id, snapshot_id) REFERENCES entity_snapshots(context_id, entity_id, id)) SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE entity_current_snapshots (context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), entity_id UUID PRIMARY KEY REFERENCES entities(id), snapshot_id UUID NOT NULL REFERENCES entity_snapshots(id), updated_at TXID NOT NULL, UNIQUE (context_id, entity_id), FOREIGN KEY (context_id, entity_id) REFERENCES entities(context_id, id), FOREIGN KEY (context_id, entity_id, snapshot_id) REFERENCES entity_snapshots(context_id, entity_id, id)) SYNC TWO WAY SYNC CONFLICT KEEP LATEST;
CREATE TABLE entity_snapshot_links (id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), entity_id UUID NOT NULL REFERENCES entities(id), predecessor_snapshot_id UUID NOT NULL REFERENCES entity_snapshots(id), successor_snapshot_id UUID NOT NULL REFERENCES entity_snapshots(id), created_at TXID NOT NULL, UNIQUE (context_id, entity_id, predecessor_snapshot_id, successor_snapshot_id), UNIQUE (context_id, entity_id, successor_snapshot_id), FOREIGN KEY (context_id, entity_id) REFERENCES entities(context_id, id), FOREIGN KEY (context_id, entity_id, predecessor_snapshot_id) REFERENCES entity_snapshots(context_id, entity_id, id), FOREIGN KEY (context_id, entity_id, successor_snapshot_id) REFERENCES entity_snapshots(context_id, entity_id, id)) IMMUTABLE SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE intention_snapshots (id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), intention_id UUID NOT NULL REFERENCES intentions(id), description TEXT NOT NULL, status TEXT NOT NULL, origin TEXT NOT NULL, properties JSON, tags JSON, valid_from TXID NOT NULL, valid_to TXID, UNIQUE (context_id, id), UNIQUE (context_id, intention_id, id), FOREIGN KEY (context_id, intention_id) REFERENCES intentions(context_id, id)) IMMUTABLE SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE intention_current_snapshots (context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), intention_id UUID PRIMARY KEY REFERENCES intentions(id), snapshot_id UUID NOT NULL REFERENCES intention_snapshots(id), updated_at TXID NOT NULL, UNIQUE (context_id, intention_id), FOREIGN KEY (context_id, intention_id) REFERENCES intentions(context_id, id), FOREIGN KEY (context_id, intention_id, snapshot_id) REFERENCES intention_snapshots(context_id, intention_id, id)) SYNC TWO WAY SYNC CONFLICT KEEP LATEST;
CREATE TABLE intention_snapshot_links (id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), intention_id UUID NOT NULL REFERENCES intentions(id), predecessor_snapshot_id UUID NOT NULL REFERENCES intention_snapshots(id), successor_snapshot_id UUID NOT NULL REFERENCES intention_snapshots(id), created_at TXID NOT NULL, UNIQUE (context_id, intention_id, predecessor_snapshot_id, successor_snapshot_id), UNIQUE (context_id, intention_id, successor_snapshot_id), FOREIGN KEY (context_id, intention_id) REFERENCES intentions(context_id, id), FOREIGN KEY (context_id, intention_id, predecessor_snapshot_id) REFERENCES intention_snapshots(context_id, intention_id, id), FOREIGN KEY (context_id, intention_id, successor_snapshot_id) REFERENCES intention_snapshots(context_id, intention_id, id)) IMMUTABLE SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE decision_intention_citations (id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), decision_id UUID NOT NULL REFERENCES decisions(id), intention_id UUID NOT NULL REFERENCES intentions(id), snapshot_id UUID NOT NULL REFERENCES intention_snapshots(id), created_at TXID NOT NULL, UNIQUE (context_id, decision_id, intention_id), FOREIGN KEY (context_id, decision_id) REFERENCES decisions(context_id, id), FOREIGN KEY (context_id, intention_id) REFERENCES intentions(context_id, id), FOREIGN KEY (context_id, intention_id, snapshot_id) REFERENCES intention_snapshots(context_id, intention_id, id)) IMMUTABLE SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE approvals (id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), decision_id UUID NOT NULL REFERENCES decisions(id), approver_id TEXT NOT NULL, level TEXT NOT NULL, rationale TEXT, created_at TXID NOT NULL, UNIQUE (context_id, id), FOREIGN KEY (context_id, decision_id) REFERENCES decisions(context_id, id)) SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE audit_log (id UUID PRIMARY KEY, txid TXID NOT NULL, operation TEXT NOT NULL, actor TEXT NOT NULL, reason TEXT, target_kind TEXT NOT NULL, target_id UUID NOT NULL, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), outcome_recorded_at TXID, payload JSON) SYNC OFF;
CREATE TABLE precedent_matches (id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), new_decision_id UUID NOT NULL REFERENCES decisions(id), precedent_decision_id UUID NOT NULL REFERENCES decisions(id), served_intention_ids JSON NOT NULL DEFAULT '[]', matched_precedent_outcome_success BOOLEAN NOT NULL, detected_at TXID NOT NULL, UNIQUE (context_id, new_decision_id, precedent_decision_id), FOREIGN KEY (context_id, new_decision_id) REFERENCES decisions(context_id, id), FOREIGN KEY (context_id, precedent_decision_id) REFERENCES decisions(context_id, id)) IMMUTABLE SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE cg_learned_skills (id TEXT PRIMARY KEY, description TEXT NOT NULL, rule TEXT NOT NULL, effect TEXT, apply_strategy TEXT, provenance TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT true, held_for_review BOOLEAN NOT NULL DEFAULT false, fire_right INTEGER NOT NULL DEFAULT 0, fire_wrong INTEGER NOT NULL DEFAULT 0, created_at TXID NOT NULL) SYNC TWO WAY SYNC CONFLICT KEEP LATEST;
CREATE TABLE cg_teaching_events (id TEXT PRIMARY KEY, skill_id TEXT, corrected_item_id TEXT NOT NULL, kind TEXT NOT NULL, content TEXT NOT NULL, created_at TXID NOT NULL) SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE cg_skill_firing_trace (id TEXT PRIMARY KEY, skill_id TEXT NOT NULL, capture_id TEXT NOT NULL, correct INTEGER, effect_entity_key TEXT, effect_entity_name TEXT, effect_from_type TEXT, effect_to_type TEXT, created_at TXID NOT NULL) SYNC OFF;
CREATE TABLE cg_review_cursor (id TEXT PRIMARY KEY, position INTEGER NOT NULL DEFAULT 0, is_local BOOLEAN NOT NULL DEFAULT true, updated_at TXID NOT NULL) SYNC OFF;
CREATE TABLE cg_overlay_entries (id TEXT PRIMARY KEY, item_id TEXT NOT NULL, kind TEXT NOT NULL, value TEXT, reversed BOOLEAN NOT NULL DEFAULT false, created_at TXID NOT NULL) SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE cg_compensation_events (id TEXT PRIMARY KEY, reversed_overlay_id TEXT NOT NULL, kind TEXT NOT NULL, content TEXT NOT NULL, created_at TXID NOT NULL) SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE cg_pending_review_items (id TEXT PRIMARY KEY, acted_on BOOLEAN NOT NULL DEFAULT false, content TEXT, legal_vocab TEXT, created_at TXID NOT NULL) SYNC OFF;
CREATE TABLE cg_source_chunks (id TEXT PRIMARY KEY, digest_id TEXT NOT NULL, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), seq INTEGER NOT NULL, content TEXT NOT NULL, content_hash TEXT NOT NULL, byte_len INTEGER NOT NULL, created_at TXID NOT NULL, created_at_ms INTEGER NOT NULL) SYNC OFF;
CREATE TABLE cg_retrieval_touches (digest_id TEXT PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), touch_count INTEGER NOT NULL DEFAULT 0, last_touched_at TXID NOT NULL) SYNC OFF;
CREATE TABLE cg_understanding_completions (id TEXT PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), model TEXT NOT NULL, receipt JSON, completed_at TXID NOT NULL) SYNC OFF;
CREATE TABLE cg_local_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TXID NOT NULL) SYNC OFF;
CREATE TABLE cg_runtime_models (id UUID PRIMARY KEY, context_label TEXT NOT NULL, model_key TEXT NOT NULL, advertised_context_tokens INTEGER NOT NULL, default_for_context BOOLEAN NOT NULL, created_at TXID NOT NULL) SYNC OFF;
CREATE TABLE cg_changed_cursors (context_id UUID PRIMARY KEY, last_seen_tx TXID NOT NULL, updated_at TXID NOT NULL) SYNC OFF;
CREATE TABLE cg_subscription_receipts (sink_name TEXT NOT NULL, action_id TEXT NOT NULL, recorded_at TXID NOT NULL, PRIMARY KEY (sink_name, action_id)) SYNC OFF;
CREATE TABLE entity_reference_embeddings_1024 (id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), entity_id UUID NOT NULL, label TEXT, vector VECTOR(1024), embedding_space_id TEXT NOT NULL REFERENCES embedding_spaces(embedding_space_id), produced_by JSON, created_at TXID NOT NULL, UNIQUE (entity_id, label), UNIQUE (context_id, id), FOREIGN KEY (context_id, entity_id) REFERENCES entities(context_id, id));
CREATE TABLE work_inputs (job_id TEXT NOT NULL);

CREATE INDEX idx_events_source_stream ON events (context_id, connector_id, source_instance_ref, seq);
CREATE INDEX idx_events_session ON events (context_id, connector_id, session_ref, seq);
CREATE INDEX idx_events_source_key ON events (context_id, connector_id, session_ref, source_event_key);
CREATE INDEX idx_events_source_time ON events (context_id, connector_id, occurred_at, seq);
CREATE INDEX idx_events_author_kind ON events (context_id, author, kind, seq);
CREATE INDEX idx_event_anchors_exact ON event_anchors (context_id, key, value, identity_value);
CREATE INDEX idx_event_anchors_physical_correlation_scope ON event_anchors (correlation_scope_hash, context_id, event_id);
CREATE INDEX idx_event_anchors_event ON event_anchors (event_id, context_id, declaration_version, key, identity_value);
CREATE INDEX idx_edges_source_context_type ON edges (source_id, context_id, edge_type);
CREATE INDEX idx_edges_target_context_type ON edges (target_id, context_id, edge_type);
CREATE INDEX idx_decisions_id_status ON decisions (id, status);
CREATE INDEX idx_evidence_embedding_handles_producer_system ON evidence_embedding_handles (producer_system);
CREATE INDEX idx_entity_reference_embedding_handles_producer_system ON entity_reference_embedding_handles (producer_system);
CREATE INDEX idx_digest_embedding_handles_producer_system ON digest_embedding_handles (producer_system);
CREATE INDEX idx_adapter_coverage_gaps_page ON adapter_coverage_gaps (context_id, connector_id, id);
CREATE INDEX idx_event_interpretation_source_events_generation ON event_interpretation_source_events (generation_id, context_id, ordinal);
CREATE INDEX idx_event_interpretation_anchors_exact ON event_interpretation_anchors (context_id, generation_id, key, canonical_value, identity_value);
CREATE INDEX idx_event_search_source_events_generation ON event_search_source_events (generation_id, context_id, ordinal);
CREATE INDEX idx_event_search_source_events_cursor_range ON event_search_source_events (context_id, generation_id, connector_id, source_instance_ref, source_sequence, ordinal);
CREATE INDEX event_search_passages_active_idx ON event_search_passages (context_id, generation_id, is_current, is_searchable);
CREATE INDEX event_search_passages_generation_ordinal_idx ON event_search_passages (generation_id, passage_ordinal);
CREATE INDEX event_search_passages_connector_idx ON event_search_passages (context_id, generation_id, is_current, connector_id);
CREATE INDEX event_search_passages_session_idx ON event_search_passages (context_id, generation_id, is_current, session_ref);
CREATE INDEX event_search_passages_source_idx ON event_search_passages (context_id, generation_id, is_current, source_instance_ref);
CREATE INDEX event_search_passage_sources_passage_idx ON event_search_passage_sources (passage_id, context_id, source_order);

-- Second texts for a table declared above: the program declares one or the other in a store.
-- Each is declared in a store of its own, after the tables above that it references.

CREATE TABLE events (id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), connector_id TEXT NOT NULL, adapter_version TEXT NOT NULL, anchor_declaration_version TEXT NOT NULL, source_instance_ref TEXT NOT NULL, session_ref TEXT NOT NULL, source_event_key TEXT NOT NULL, source_position JSON NOT NULL, seq INTEGER NOT NULL, content_hash TEXT NOT NULL, anchor_count INTEGER NOT NULL, anchor_set_hash TEXT NOT NULL, occurred_at TIMESTAMP, author TEXT NOT NULL, kind TEXT NOT NULL, render_role TEXT NOT NULL, interaction_ref TEXT, text TEXT, payload JSON NOT NULL DEFAULT '{}', anchors JSON NOT NULL DEFAULT '{}', source_remainder JSON NOT NULL DEFAULT '{}', coverage TEXT NOT NULL, UNIQUE (context_id, id), UNIQUE (context_id, connector_id, session_ref, source_event_key), UNIQUE (context_id, connector_id, source_instance_ref, seq)) SYNC PUSH ONLY SYNC CONFLICT KEEP FIRST IMMUTABLE DELIVERY MANIFEST OVER event_anchors MAINTAIN COUNT (context_id), (context_id, connector_id, source_instance_ref);
CREATE TABLE event_anchors (id UUID PRIMARY KEY, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), event_id UUID NOT NULL REFERENCES events(id), correlation_scope_hash TEXT NOT NULL, declaration_version TEXT NOT NULL, connector_id TEXT NOT NULL, source_instance_ref TEXT NOT NULL, session_ref TEXT NOT NULL, render_role TEXT NOT NULL, interaction_ref TEXT, key TEXT NOT NULL, value TEXT NOT NULL, identity_value TEXT NOT NULL, original_value JSON NOT NULL, UNIQUE (context_id, id), UNIQUE (context_id, event_id, declaration_version, key, identity_value), FOREIGN KEY (context_id, event_id) REFERENCES events(context_id, id)) SYNC PUSH ONLY SYNC CONFLICT KEEP FIRST IMMUTABLE MAINTAIN COUNT NONE;
CREATE TABLE conflicts (id UUID NOT NULL UNIQUE, context_id UUID CONTEXT_ID NOT NULL REFERENCES contexts(id), older_decision_id UUID NOT NULL REFERENCES decisions(id), newer_decision_id UUID NOT NULL REFERENCES decisions(id), threatened_intention_ids JSON NOT NULL DEFAULT '[]', intention_in_tension BOOLEAN NOT NULL, detected_at TXID NOT NULL, PRIMARY KEY (context_id, older_decision_id, newer_decision_id), FOREIGN KEY (context_id, older_decision_id) REFERENCES decisions(context_id, id), FOREIGN KEY (context_id, newer_decision_id) REFERENCES decisions(context_id, id)) IMMUTABLE SYNC TWO WAY SYNC CONFLICT KEEP FIRST;
CREATE TABLE digests (id UUID PRIMARY KEY, embedding VECTOR(384));
CREATE TABLE observations (id UUID PRIMARY KEY, data JSON NOT NULL);
CREATE TABLE cg_schema_version (id INTEGER PRIMARY KEY, version INTEGER NOT NULL, installed_at TXID NOT NULL);
